INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_8d2c47a91e05b3f6d7c418', 'Board pre-read - fundraising section', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "robert@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'Board pre-read - fundraising section\nLeonard, for the Jul 16 board.\n\nTable\nOne row per firm we''ve spoken to since the April update. Status: Passed, Active, Cold.\n\nMoney\nCommitted: a verbal yes from a named investor or angel, with an amount.\nInterested: said they''d look at it, no amount.\nShow committed at the top, it''s the first thing Griffin asks.\n\nNotes\nKeep it to one page. Robert adds the product slide, Arthur the tech slide.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 69, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 69, "end": 75, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 75, "end": 163, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 163, "end": 169, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 169, "end": 351, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 351, "end": 357, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 357, "end": 432, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '3601958fa7', 'f_8d2c47a91e05b3f6d7c418', '2025-07-08T18:00:00Z', '2025-07-10T16:12:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_3b9e61c04d7a52e8f1a6c2', 'Board pre-read - fundraising section (Oct 14)', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "robert@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'Board pre-read - fundraising section (Oct 14)\nLeonard, Sep 26. Same layout as the other sections of the pre-read.\n\nWho goes in the table\nOne row per name on the 2025 game investor list, angels included. The list has a few names twice, and a repeated name is still one row. Add any firm not on the list that we''ve had a pitch call or meeting with since we kicked off the bridge on Sep 3. A call counts when it''s on our calendars. Investment talks only, strategic investors included. Service or work-for-hire deals, publishing-only talks and calls with other engine companies don''t go in.\n\nStatus, as of end of day Tue Sep 30 (Pacific)\nPassed: they told us no for this round in writing. A pass one of us heard by phone counts once it is written in #bridge-pitch.\nIn talks: we''ve had a call or meeting this round and they haven''t passed.\nAwaiting reply: we reached out this round, no call yet and no answer.\nNot contacted this round: nothing from us since Sep 3.\nA partner writing from their own address counts for their firm. If the name doesn''t ring a bell, check contacts and the earlier threads.\n\nLast two-way contact\nDate of the latest message or call where both sides took part, Pacific.\n\nMoney\nCommitted: signed SAFE only, meaning the DocuSign Completed notice is in.\nSoft-circled: a yes in writing with an amount that isn''t signed yet. Use the latest amount the investor gave us.\nPut the committed and soft-circled totals at the bottom of the sheet.\n\nBuild access\nFor firms in talks: whether they are on the tester list for the current internal Zombie Match 3D build, TestFlight on iOS and the Play internal test track on Android. The public App Store page doesn''t count. Arthur tracks the tester adds.\n', '[{"start": 0, "end": 46, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 46, "end": 115, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 115, "end": 137, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 137, "end": 588, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 588, "end": 634, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 634, "end": 1098, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1098, "end": 1119, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1119, "end": 1192, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1192, "end": 1198, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1198, "end": 1456, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1456, "end": 1469, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1469, "end": 1708, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '1b0d9b5d65', 'f_3b9e61c04d7a52e8f1a6c2', '2025-09-26T18:00:00Z', '2025-09-26T18:41:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_c61a0e93b7d24f58a2e917', 'README - Oct 14 board materials', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co"]', 'private', E'README - Oct 14 board materials\nOne file per section in this folder, named "<section> - Oct 14 board", e.g. "Fundraising - Oct 14 board" or "Product - Oct 14 board".\nGoogle Sheets or Docs only, no uploads, so I can link them from the deck.\nLeonard collects everything on Monday Oct 6.\n', '[{"start": 0, "end": 32, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 32, "end": 285, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '681e98b8a9', 'f_c61a0e93b7d24f58a2e917', '2025-09-26T18:30:00Z', '2025-09-26T18:33:00Z');
