INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('frederick.stone@harmonygames.co/1844724419788800011', 'frederick.stone@harmonygames.co', 'Fred, I''m flying to LA tomorrow morning for the Griffin AGM and the Dentsu meeting, so can you own the fundraising section of the Oct 14 pre', NULL);
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('frederick.stone@harmonygames.co/<CAxDeR9CSc9iEY-zACLQaU5Hff5KY0zkGE4PQ9iK@mail.gmail.com>', 'frederick.stone@harmonygames.co/1844724419788800011', 'frederick.stone@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Fred, I''m flying to LA tomorrow morning for the Griffin AGM and the Dentsu meeting, so can you own the fundraising section of the Oct 14 pre', 1759266300000, '2025-09-30T21:05:00Z', 1983, 'Oct 14 board pre-read - fundraising section', 'leonard.hayes@harmonygames.co', 'Leonard Hayes', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '["Robert <robert@harmonygames.co>", "Arthur Blake <arthur.blake@harmonygames.co>"]', '[]', '[]', E'Fred,\r\n\r\nI''m flying to LA tomorrow morning for the Griffin AGM and the Dentsu meeting, so can you own the fundraising section of the Oct 14 pre-read? I''ll stitch it into the deck when I''m back.\r\n\r\nWhat I need is where every firm on the 2025 game investor list, plus anyone we''ve had a call with since the Sep 3 kickoff who isn''t on it, stands as of tonight. One sheet, one row per firm. Please use the buckets and definitions in the board pre-read template so it matches the other sections. The money lines matter most, the board will ask what''s actually committed.\r\n\r\nPlease put the sheet in your Board - Oct 14 2025 folder, the README in that folder says how to name it. Whatever the Existing Investor Update card says to do for firms that pass, do that too. The Board Deck card says which numbers the slide takes, so once it''s done reply here with the numbers the fundraising slide needs. I put Monday''s review on your calendar so we can go through it together.\r\n\r\nRobert asked about emailing the pipeline straight to the board. Let''s not, it goes in the deck.\r\n\r\nThanks,\r\nLeonard', NULL, '[{"name": "Message-ID", "value": "<CAxDeR9CSc9iEY-zACLQaU5Hff5KY0zkGE4PQ9iK@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 30 Sep 2025 21:05:00 +0000"}, {"name": "Subject", "value": "Oct 14 board pre-read - fundraising section"}, {"name": "From", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}, {"name": "Cc", "value": "Robert <robert@harmonygames.co>, Arthur Blake <arthur.blake@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
